export interface Entry {
  id: string;
  lang: LangId;
  tags: readonly string[];
}

export function byLang(entries: Entry[], lang: LangId): Entry[] {
  return entries.filter((e) => e.lang === lang);
}

export type Shape =
  | { kind: 'circle'; r: number }
  | { kind: 'rect'; w: number; h: number };

export const isCircle = (s: Shape): s is Extract<Shape, { kind: 'circle' }> =>
  s.kind === 'circle';

export function indexBy<T, K extends keyof T>(items: T[], key: K): Map<T[K], T> {
  const out = new Map<T[K], T>();
  for (const item of items) {
    out.set(item[key], item);
  }
  return out;
}

export const STAGES = ['base', 'shift', 'lower', 'raise'] as const;

export type Stage = (typeof STAGES)[number];

export interface Progress {
  stage: Stage;
  accuracy: number;
  medianLatencyMs: number;
}

export async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init);
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  return (await res.json()) as T;
}

type Event =
  | { type: 'keystroke'; char: string; latencyMs: number }
  | { type: 'backspace' }
  | { type: 'done'; wpm: number };

export function reduce(state: State, event: Event): State {
  switch (event.type) {
    case 'keystroke':
      return { ...state, typed: state.typed + event.char };
    case 'backspace':
      return { ...state, typed: state.typed.slice(0, -1) };
    case 'done':
      return { ...state, wpm: event.wpm, finished: true };
  }
}

export function partition<T, U extends T>(
  items: readonly T[],
  guard: (item: T) => item is U,
): [U[], Exclude<T, U>[]] {
  const hits: U[] = [];
  const rest: Exclude<T, U>[] = [];
  for (const item of items) {
    if (guard(item)) hits.push(item);
    else rest.push(item as Exclude<T, U>);
  }
  return [hits, rest];
}

export interface Repository<T extends { id: string }> {
  get(id: string): Promise<T | null>;
  save(item: T): Promise<void>;
}

export class MemoryRepo<T extends { id: string }> implements Repository<T> {
  private readonly rows = new Map<string, T>();

  async get(id: string): Promise<T | null> {
    return this.rows.get(id) ?? null;
  }

  async save(item: T): Promise<void> {
    this.rows.set(item.id, item);
  }
}

export type Nullable<T> = { [K in keyof T]: T[K] | null };

export function blank<T extends object>(shape: T): Nullable<T> {
  const out = {} as Nullable<T>;
  for (const key of Object.keys(shape) as (keyof T)[]) {
    out[key] = null;
  }
  return out;
}

export async function tryCatch<T>(
  fn: () => Promise<T>,
): Promise<{ ok: true; value: T } | { ok: false; error: Error }> {
  try {
    return { ok: true, value: await fn() };
  } catch (cause) {
    return { ok: false, error: cause instanceof Error ? cause : new Error(String(cause)) };
  }
}

type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };

type Getters<T> = {
  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
};

export function ok<T>(value: T): Result<T> {
  return { ok: true, value };
}

type Paths<T> = T extends object
  ? {
      [K in keyof T & string]: T[K] extends object ? `${K}.${Paths<T[K]>}` | K : K;
    }[keyof T & string]
  : never;

export function getIn<T extends object>(obj: T, path: Paths<T>): unknown {
  return path.split('.').reduce<unknown>((acc, key) => (acc as never)?.[key], obj);
}

type Schema<T> = { [K in keyof T]: (v: unknown) => v is T[K] };

export function validate<T extends object>(
  raw: Record<string, unknown>,
  schema: Schema<T>,
): { value: T; problems: string[] } {
  const problems: string[] = [];
  for (const key of Object.keys(schema) as (keyof T & string)[]) {
    if (!schema[key](raw[key])) problems.push(`bad field: ${key}`);
  }
  return { value: raw as T, problems };
}

export function createStore<S, A extends { type: string }>(
  reducer: (state: S, action: A) => S,
  initial: S,
) {
  let state = initial;
  const listeners = new Set<(s: S) => void>();

  return {
    getState: (): Readonly<S> => state,
    dispatch(action: A): void {
      state = reducer(state, action);
      listeners.forEach((fn) => fn(state));
    },
    subscribe(fn: (s: S) => void): () => void {
      listeners.add(fn);
      return () => void listeners.delete(fn);
    },
  };
}

type EventMap = {
  keystroke: { char: string; correct: boolean };
  drillDone: { wpm: number };
};

type Listeners = {
  [K in keyof EventMap as `on${Capitalize<K>}`]?: (payload: EventMap[K]) => void;
};

export function dispatch<K extends keyof EventMap>(
  listeners: Listeners,
  key: K,
  payload: EventMap[K],
): void {
  const name = `on${key[0]!.toUpperCase()}${key.slice(1)}` as keyof Listeners;
  (listeners[name] as ((p: EventMap[K]) => void) | undefined)?.(payload);
}
